SELECT 

WHERE h.tenant_id = #{tenantId, jdbcType=BIGINT}
  AND h.use_at = 'Y'
  AND d.purchase_request_detail_id IN
  #{id, jdbcType=BIGINT}
ORDER BY h.request_no, d.line_no

SELECT 

WHERE d.tenant_id = #{tenantId, jdbcType=BIGINT}
  AND d.purchase_confirm_id = #{purchaseConfirmId, jdbcType=BIGINT}
ORDER BY h.request_no, d.line_no

SELECT pc.purchase_confirm_id AS purchaseConfirmId, pc.confirm_no AS confirmNo, pc.confirm_dt AS confirmDt, cu.user_nm AS confirmerName, pc.currency_code AS currencyCode, pc.total_amt AS totalAmt, (SELECT count(DISTINCT d.purchase_request_id) FROM tb_purchase_request_dt d WHERE d.purchase_confirm_id = pc.purchase_confirm_id AND d.tenant_id = pc.tenant_id) AS requestCount, pc.remark AS remark, pc.use_at AS useAt FROM tb_purchase_confirm_hd pc LEFT JOIN tb_user cu ON cu.user_id = pc.confirmer_id WHERE pc.tenant_id = #{tenantId, jdbcType=BIGINT}
AND pc.use_at = #{useAt}
AND pc.confirm_dt >= CAST(#{fromDt} AS date)
AND pc.confirm_dt <= CAST(#{toDt} AS date)
AND (pc.confirm_no ILIKE '%' || #{keyword} || '%' OR cu.user_nm ILIKE '%' || #{keyword} || '%' OR pc.remark ILIKE '%' || #{keyword} || '%' OR EXISTS (SELECT 1 FROM tb_purchase_request_dt d JOIN tb_purchase_request_hd h ON h.purchase_request_id = d.purchase_request_id AND h.tenant_id = d.tenant_id WHERE d.purchase_confirm_id = pc.purchase_confirm_id AND d.tenant_id = pc.tenant_id AND h.request_no ILIKE '%' || #{keyword} || '%'))
ORDER BY pc.confirm_dt DESC, pc.confirm_no DESC LIMIT 200

SELECT pc.use_at
FROM tb_purchase_confirm_hd pc
WHERE pc.purchase_confirm_id = #{purchaseConfirmId, jdbcType=BIGINT}
  AND pc.tenant_id = #{tenantId, jdbcType=BIGINT}
FOR UPDATE OF pc

SELECT EXISTS (
    SELECT 1 FROM tb_warehouse
    WHERE warehouse_id = #{id, jdbcType=BIGINT}
      AND tenant_id = #{tenantId, jdbcType=BIGINT}
      AND disuse_at = 'N'
)

SELECT EXISTS (
    SELECT 1 FROM tb_customer_info
    WHERE customer_id = #{id, jdbcType=BIGINT}
      AND tenant_id = #{tenantId, jdbcType=BIGINT}
      AND use_at = 'Y'
)

INSERT INTO tb_purchase_confirm_hd (
    tenant_id, confirm_no, confirm_dt, confirmer_id, currency_code, total_amt, remark, created_by
) VALUES (
    #{tenantId, jdbcType=BIGINT}, #{confirmNo}, CAST(#{confirmDt} AS date), #{confirmerId, jdbcType=BIGINT},
    #{currencyCode}, #{totalAmt, jdbcType=NUMERIC}, #{remark}, #{createdBy}
)
RETURNING purchase_confirm_id

