UPDATE tb_purchase_request_dt
SET order_close_at = #{orderCloseAt},
    updated_by = #{updatedBy},
    updated_at = now()
WHERE purchase_request_detail_id = #{purchaseRequestDetailId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND purchase_confirm_id = #{purchaseConfirmId, jdbcType=BIGINT}
  AND order_close_at <> #{orderCloseAt}

